CREATE OR REPLACE FUNCTION public.add_gratitude_statement(p_entry_date date, p_statement text, p_mood text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_row_id uuid;
  v_statements jsonb;
  v_moods jsonb;
  v_index int;
begin
  if v_user_id is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  -- Lock row if exists
  select id, coalesce(statements, '[]'::jsonb), coalesce(moods, '{}'::jsonb)
    into v_row_id, v_statements, v_moods
  from public.gratitude_entries
  where user_id = v_user_id and entry_date = p_entry_date
  for update;

  if found then
    v_index := coalesce(jsonb_array_length(v_statements), 0);

    update public.gratitude_entries
    set statements = v_statements || to_jsonb(p_statement),
        moods = case when p_mood is not null
                     then jsonb_set(v_moods, array[(v_index)::text], to_jsonb(p_mood), true)
                     else v_moods end,
        updated_at = now()
    where id = v_row_id;
  else
    -- Create new entry for that date with the first statement
    insert into public.gratitude_entries (user_id, entry_date, statements, moods, created_at, updated_at)
    values (
      v_user_id,
      p_entry_date,
      ('[]'::jsonb || to_jsonb(p_statement)),
      (case when p_mood is not null then jsonb_build_object('0', p_mood) else '{}'::jsonb end),
      now(),
      now()
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.analyze_notification_query_performance()
 RETURNS TABLE(query_step text, execution_time_ms numeric, rows_processed bigint, notes text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
    start_time TIMESTAMP;
    end_time TIMESTAMP;
    user_count BIGINT;
    token_count BIGINT;
BEGIN
    -- Step 1: Time the user selection query
    start_time := clock_timestamp();

    SELECT COUNT(*) INTO user_count
    FROM public.profiles p
    WHERE p.notification_time IS NOT NULL
        AND p.timezone IS NOT NULL
        AND EXTRACT(HOUR FROM p.notification_time) = EXTRACT(HOUR FROM ((NOW() + INTERVAL '1 hour') AT TIME ZONE p.timezone));

    end_time := clock_timestamp();

    RETURN QUERY SELECT 
        'User Selection Query'::TEXT,
        EXTRACT(EPOCH FROM (end_time - start_time)) * 1000,
        user_count,
        'Users matching next hour notification time'::TEXT;

    -- Step 2: Time the token join query
    start_time := clock_timestamp();

    SELECT COUNT(*) INTO token_count
    FROM public.profiles p
    JOIN public.push_tokens pt ON p.id = pt.user_id
    WHERE p.notification_time IS NOT NULL
        AND p.timezone IS NOT NULL
        AND EXTRACT(HOUR FROM p.notification_time) = EXTRACT(HOUR FROM ((NOW() + INTERVAL '1 hour') AT TIME ZONE p.timezone));

    end_time := clock_timestamp();

    RETURN QUERY SELECT 
        'Token Join Query'::TEXT,
        EXTRACT(EPOCH FROM (end_time - start_time)) * 1000,
        token_count,
        'Total tokens for users needing notifications'::TEXT;

    -- Step 3: Overall system stats
    RETURN QUERY SELECT 
        'Index Usage Check'::TEXT,
        0::NUMERIC,
        0::BIGINT,
        'Use EXPLAIN ANALYZE on main query to verify index usage'::TEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.attach_media_to_statement(p_entry_date date, p_statement_index integer, p_kind text, p_storage_path text, p_mime_type text, p_bytes integer, p_duration_ms integer DEFAULT NULL::integer, p_width integer DEFAULT NULL::integer, p_height integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_entry_id uuid;
  v_len integer;
  v_new_id uuid;
  v_expected_prefix text;
  v_existing_count integer;
  v_daily_cap CONSTANT integer := 10;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_kind NOT IN ('image', 'audio') THEN
    RAISE EXCEPTION 'Invalid attachment kind: %', p_kind USING ERRCODE = '22023';
  END IF;

  -- Enforce that the storage path lives under the user's own folder.
  v_expected_prefix := v_user_id::text || '/';
  IF p_storage_path IS NULL OR position(v_expected_prefix IN p_storage_path) <> 1 THEN
    RAISE EXCEPTION 'Storage path must start with %', v_expected_prefix USING ERRCODE = '22023';
  END IF;

  SELECT id, coalesce(jsonb_array_length(statements), 0)
    INTO v_entry_id, v_len
  FROM public.gratitude_entries
  WHERE user_id = v_user_id AND entry_date = p_entry_date
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Entry not found for date %', p_entry_date USING ERRCODE = 'P0002';
  END IF;

  IF p_statement_index < 0 OR p_statement_index >= v_len THEN
    RAISE EXCEPTION 'Invalid statement index % (length %)', p_statement_index, v_len
      USING ERRCODE = '22003';
  END IF;

  -- Per-day cap per kind. Keep the row lock from the entry above in effect so
  -- two concurrent uploads can't both race past the limit.
  SELECT count(*) INTO v_existing_count
  FROM public.gratitude_attachments
  WHERE user_id   = v_user_id
    AND entry_date = p_entry_date
    AND kind       = p_kind;

  IF v_existing_count >= v_daily_cap THEN
    RAISE EXCEPTION 'ATTACHMENT_DAILY_LIMIT_REACHED:%:%', p_kind, v_daily_cap
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.gratitude_attachments (
    user_id, entry_id, entry_date, statement_index,
    kind, storage_path, mime_type, bytes,
    duration_ms, width, height
  ) VALUES (
    v_user_id, v_entry_id, p_entry_date, p_statement_index,
    p_kind, p_storage_path, p_mime_type, p_bytes,
    p_duration_ms, p_width, p_height
  )
  RETURNING id INTO v_new_id;

  -- Touch the parent entry so query cache invalidation behaves like a normal edit.
  UPDATE public.gratitude_entries
  SET updated_at = now()
  WHERE id = v_entry_id;

  RETURN v_new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_streak(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current_streak integer := 0;
  v_check_date date := current_date;
  v_has_entry boolean;
  v_grace_used boolean := false;
begin
  if p_user_id is null then
    raise exception 'User ID cannot be null';
  end if;

  loop
    select exists(
      select 1
      from public.gratitude_entries
      where user_id = p_user_id
        and entry_date = v_check_date
        and coalesce(jsonb_array_length(statements), 0) > 0
    ) into v_has_entry;

    if v_has_entry then
      v_current_streak := v_current_streak + 1;
      v_check_date := v_check_date - interval '1 day';
    elsif v_check_date = current_date and not v_grace_used then
      -- Grace: missing "today" doesn't break the streak if yesterday exists.
      v_grace_used := true;
      v_check_date := v_check_date - interval '1 day';
    else
      exit;
    end if;

    if v_current_streak >= 3650 then
      exit; -- safety
    end if;
  end loop;

  return v_current_streak;
end;
$function$

CREATE OR REPLACE FUNCTION public.check_username_availability(p_username text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  username_exists BOOLEAN;
BEGIN
  IF p_username IS NULL OR TRIM(p_username) = '' THEN
    RETURN FALSE;
  END IF;

  -- Check if any normalized username matches
  SELECT COUNT(*) > 0 INTO username_exists
  FROM profiles 
  WHERE username IS NOT NULL 
  AND normalize_turkish(username) = normalize_turkish(p_username);

  RETURN NOT username_exists;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_stale_tokens(p_max_age_days integer DEFAULT 90)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  deleted_count integer := 0;
BEGIN
  DELETE FROM public.push_tokens
  WHERE created_at < NOW() - (p_max_age_days || ' days')::interval;

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$function$

