CREATE OR REPLACE FUNCTION public.delete_gratitude_entry_by_date(p_entry_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_deleted_count INTEGER;
BEGIN
  -- Get authenticated user ID
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'User not authenticated';
  END IF;

  -- Validate date format and reasonable bounds
  IF p_entry_date IS NULL THEN
    RAISE EXCEPTION 'Entry date cannot be null';
  END IF;

  -- Delete the entire entry atomically
  DELETE FROM gratitude_entries
  WHERE user_id = v_user_id AND entry_date = p_entry_date;

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

  -- Update user streak after deletion (important for streak accuracy)
  PERFORM update_user_streak(v_user_id);

  -- Log the operation for debugging (optional)
  -- Could be removed in production for performance
  IF v_deleted_count > 0 THEN
    -- Entry was successfully deleted
    NULL; -- Placeholder for potential logging
  ELSE
    -- No entry found for the given date (not an error, just info)
    NULL; -- Could log this if needed
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_gratitude_statement(p_entry_date date, p_statement_index integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_row_id uuid;
  v_statements jsonb;
  v_moods jsonb;
  v_len int;
  v_new_statements jsonb := '[]'::jsonb;
  v_new_moods jsonb := '{}'::jsonb;
  v_i int;
  v_k text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT id, coalesce(statements, '[]'::jsonb), coalesce(moods, '{}'::jsonb)
    INTO v_row_id, v_statements, v_moods
  FROM public.gratitude_entries
  WHERE user_id = v_user_id AND entry_date = p_entry_date
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Entry not found for date %', p_entry_date USING ERRCODE = 'P0002';
  END IF;

  v_len := coalesce(jsonb_array_length(v_statements), 0);
  IF p_statement_index < 0 OR p_statement_index >= v_len THEN
    RAISE EXCEPTION 'Invalid statement index %', p_statement_index USING ERRCODE = '22003';
  END IF;

  -- Rebuild statements[] without the deleted index.
  FOR v_i IN 0 .. v_len - 1 LOOP
    IF v_i <> p_statement_index THEN
      v_new_statements := v_new_statements || (v_statements -> v_i);
    END IF;
  END LOOP;

  -- Re-key moods{} by shifting everything above p_statement_index down by one.
  FOR v_k IN SELECT jsonb_object_keys(v_moods) LOOP
    IF v_k::int < p_statement_index THEN
      v_new_moods := v_new_moods || jsonb_build_object(v_k, v_moods -> v_k);
    ELSIF v_k::int > p_statement_index THEN
      v_new_moods := v_new_moods || jsonb_build_object((v_k::int - 1)::text, v_moods -> v_k);
    END IF;
  END LOOP;

  IF jsonb_array_length(v_new_statements) = 0 THEN
    -- Last statement removed → delete the entry row (cascades to attachments).
    DELETE FROM public.gratitude_entries WHERE id = v_row_id;
    RETURN;
  END IF;

  UPDATE public.gratitude_entries
  SET statements = v_new_statements,
      moods      = v_new_moods,
      updated_at = now()
  WHERE id = v_row_id;

  -- Shift attachment indexes atomically, then drop anything attached to the
  -- deleted statement. Order matters: delete first, then shift.
  DELETE FROM public.gratitude_attachments
  WHERE user_id = v_user_id
    AND entry_date = p_entry_date
    AND statement_index = p_statement_index;

  UPDATE public.gratitude_attachments
  SET statement_index = statement_index - 1
  WHERE user_id = v_user_id
    AND entry_date = p_entry_date
    AND statement_index > p_statement_index;
END;
$function$

CREATE OR REPLACE FUNCTION public.edit_gratitude_statement(p_entry_date date, p_statement_index integer, p_updated_statement text, p_mood text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_row_id uuid;
  v_statements jsonb;
  v_moods jsonb;
  v_len int;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT id, COALESCE(statements, '[]'::jsonb), COALESCE(moods, '{}'::jsonb)
    INTO v_row_id, v_statements, v_moods
  FROM public.gratitude_entries
  WHERE user_id = v_user_id
    AND entry_date = p_entry_date
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Entry not found for date %', p_entry_date USING ERRCODE = 'P0002';
  END IF;

  v_len := COALESCE(jsonb_array_length(v_statements), 0);
  IF p_statement_index < 0 OR p_statement_index >= v_len THEN
    RAISE EXCEPTION 'Invalid statement index %, length %', p_statement_index, v_len
      USING ERRCODE = '22003';
  END IF;

  UPDATE public.gratitude_entries
  SET statements = jsonb_set(
        v_statements,
        ARRAY[(p_statement_index)::text],
        to_jsonb(p_updated_statement),
        true
      ),
      moods = CASE
        WHEN p_mood IS NOT NULL THEN
          jsonb_set(v_moods, ARRAY[(p_statement_index)::text], to_jsonb(p_mood), true)
        ELSE
          v_moods
      END,
      updated_at = now()
  WHERE id = v_row_id;
END;
$function$

